var totalExpenseByDate = (movementList, year, month, monthCount = 1, filterMethod = () => true) => {
  const result = {
    dailyTotals: [...Array(31).keys()].map((d4) => ({
      day: d4 + 1
    }))
  };
  result.dailyTotals.forEach((t3) => {
    let index2 = 0;
    let iterable = DateUtils.getIterableCurrentMonth(year, month);
    while (index2 <= monthCount) {
      if (t3.day <= DateUtils.lastDayInMonth(iterable.year, iterable.month)) {
        const list = movementList.filter((m4) => m4.mov_ctg_type === 1 && filterMethod(m4) && m4.mov_date.getTime() >= new Date(iterable.year, iterable.month - 1, 1).getTime() && m4.mov_date.getTime() <= new Date(iterable.year, iterable.month - 1, t3.day, 23, 59, 59).getTime());
        t3[`expenseMonthCount${index2}`] = list.length;
        t3[`expenseMonth${index2}`] = list.reduce((sum, current) => Math.round((sum + current.mov_amount) * 100) / 100, 0);
      }
      index2 += 1;
      iterable = DateUtils.getIterablePreviousMonth(iterable.year, iterable.month);
    }
  });
  return result;
};

